import asyncio
import os
import platform
import sys
from dataclasses import dataclass


@dataclass
class tool:

    @staticmethod
    def clear_screen():
        os.system('cls' if platform.system() == "Windows" else 'clear')

    @staticmethod
    async def verify_modules():
        try:
            req_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "../requirements/requirements.txt"))

            process = await asyncio.create_subprocess_exec(
                sys.executable, "-m", "pip", "install", "-r", req_path,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await process.communicate()

            if process.returncode != 0:
                if stdout:
                    print(stdout.decode(errors="replace"))
                if stderr:
                    print(stderr.decode(errors="replace"))
                raise RuntimeError(f"pip install failed with exit code {process.returncode}")

        except Exception as e:
            print(f"[ERROR verify_modules] {e}")
            raise

    @staticmethod
    async def add_path_modules(data_local):
        try:
            for path in getattr(data_local, 'modules_local', []) or []:
                abs_path = os.path.abspath(os.path.join(os.path.dirname(__file__), path))
                if abs_path not in sys.path:
                    sys.path.append(abs_path)
                    if getattr(data_local, 'Debug', False):
                        print(f"[PATH] {abs_path}")
        except Exception as e:
            print(f"[ERROR add_path] {e}")
            raise

